// Renders the LED matrix as an interactive SVG, positioned from the real
// board layout (webui/board_data.js, generated by
// tools/extract_board_data.py -- see docs/LEDPWM_MATRIX.md). Board
// coordinates are millimeters with the same origin/orientation KiCad uses;
// this file just wraps them in a viewBox, no transform needed.
'use strict';

const SVG_NS = 'http://www.w3.org/2000/svg';
// MATRIX_MODE=PA24 (CH643RM.PDF 24.2.2, "8-column RGB Internal Drive") --
// 16 COM/rows (PB0-15), 24 addressable columns (8 groups x R/G/B channels,
// PA0-23). See docs/LEDPWM_MATRIX.md. Shared across all webui/*.js files
// (loaded before them) rather than redefined per file.
const MATRIX_ROWS = 16;
const MATRIX_COLS = 24;
const PIXEL_COUNT = MATRIX_ROWS * MATRIX_COLS;
const LED_RADIUS = 1.05; // mm, tuned by eye against the board's LED pitch
// Keyboard cursor ring, a little larger than an RGB diamond (half diagonal
// LED_RADIUS * 1.8 / sqrt(2) = 1.34 mm) so it shows around either kind.
// The ring crosses the neighbouring LEDs (2 mm pitch), so it has two
// tones: a wide yellow halo under a black core. One of the two always has
// 3:1 or more against what is under it (WCAG 1.4.11): yellow on unlit dots
// and the dark stage, black on lit dots and the light PCB.
const BOARD_CURSOR_RADIUS = 1.75;
const BOARD_CURSOR_HALO = 0.9; // mm, about 2.7px at 390px wide
const BOARD_CURSOR_CORE = 0.45; // mm
// A tap that hits no white LED selects a colour LED this close (mm), so
// the small diamonds are easier to hit on a phone
const BOARD_RGB_TAP_RADIUS = 3;
const BOARD_ANNOUNCE_MS = 250; // at most one #board-live update per this
// Arrow key -> unit vector in board millimetres (y grows downwards)
const BOARD_ARROWS = {
	ArrowUp: [0, -1],
	ArrowDown: [0, 1],
	ArrowLeft: [-1, 0],
	ArrowRight: [1, 0],
};

class BoardView {
	constructor(container) {
		this.container = container;
		this.frame = new Uint8Array(PIXEL_COUNT); // row-major, index = row*16+col
		this.dotByIndex = new Array(PIXEL_COUNT).fill(null);
		this.rgbDotByRef = new Map();
		// Which RGB LEDs' displayed color depends on a given (row, col)
		// cell -- an RGB LED's three channels are three ordinary cells in
		// the same `frame` array (see docs/LEDPWM_MATRIX.md), so painting
		// one of those cells needs to refresh that LED's swatch too.
		this._rgbRefsByCell = new Map();
		// (xMillimeters, yMillimeters) => bool, called while the user draws;
		// false when no LED was in reach
		this.onPaintAt = null;
		// (rgbLedInfo, { keyboard }) => void, called on clicking an RGB LED,
		// or Enter on one; keyboard is true for Enter
		this.onSelectRgb = null;
		// (xMillimeters, yMillimeters) => void, like onPaintAt but always
		// with the eraser. Delete/Backspace on the board uses it. When it is
		// not set, the board turns on #erase-mode for one onPaintAt call.
		this.onEraseAt = null;
		// When true, the RGB LEDs are paint targets (dragging over them calls
		// onPaintAt like anywhere else) instead of opening onSelectRgb.
		this.rgbBrush = false;
		this._painting = false;
		// Keyboard cursor: every LED, white and RGB, as one list of targets
		this._targets = [];
		this._cursor = 0; // index into _targets
		this._cursorEl = null;
		this._announceTimer = null;
		this._announceLast = 0;
		this._announceText = '';
		this._build();
	}

	_build() {
		const xs = BOARD_DATA.outline.map((p) => p[0]);
		const ys = BOARD_DATA.outline.map((p) => p[1]);
		const pad = 4;
		const minX = Math.min(...xs) - pad;
		const minY = Math.min(...ys) - pad;
		const w = Math.max(...xs) - minX + pad;
		const h = Math.max(...ys) - minY + pad;
		// Exposed so other code (webui/video_import.js, mapping a video frame
		// onto the board) can sample at exactly the same framing this view
		// renders at, instead of recomputing/duplicating this padding logic.
		this.bounds = { minX, minY, width: w, height: h };

		const svg = document.createElementNS(SVG_NS, 'svg');
		svg.setAttribute('viewBox', `${minX} ${minY} ${w} ${h}`);
		svg.classList.add('board-svg');
		// One focusable widget with its own keys (see _wireKeyboard). The
		// LEDs themselves stay out of the accessibility tree: the cursor
		// position and LED state go out through #board-live instead.
		svg.setAttribute('tabindex', '0');
		svg.setAttribute('role', 'application');
		svg.setAttribute('aria-roledescription', 'LED board');
		svg.setAttribute('aria-label', 'Starfish LED board');
		if (document.getElementById('board-help')) svg.setAttribute('aria-describedby', 'board-help');

		const outline = document.createElementNS(SVG_NS, 'polygon');
		outline.setAttribute(
			'points',
			BOARD_DATA.outline.map((p) => `${p[0]},${p[1]}`).join(' ')
		);
		outline.classList.add('board-outline');
		svg.appendChild(outline);

		// Silkscreen artwork, between the PCB and the LEDs. starfish_silkscreen.svg
		// is a 210x297mm Inkscape page at real scale, sharing its page
		// coordinates with the hardware repo's design/starfish_outline.svg --
		// so placing it is a pure translation: that outline's page-space
		// bounding box top-left (0.050189, 0.064966) onto BOARD_DATA.outline's.
		const outlineMinX = Math.min(...xs);
		const outlineMinY = Math.min(...ys);
		const clip = document.createElementNS(SVG_NS, 'clipPath');
		clip.id = 'board-clip';
		clip.appendChild(outline.cloneNode());
		const defs = document.createElementNS(SVG_NS, 'defs');
		defs.appendChild(clip);
		svg.appendChild(defs);
		const silkscreen = document.createElementNS(SVG_NS, 'image');
		silkscreen.setAttribute('href', 'starfish_silkscreen.svg');
		silkscreen.setAttribute('x', outlineMinX - 0.050189);
		silkscreen.setAttribute('y', outlineMinY - 0.064966);
		silkscreen.setAttribute('width', 210);
		silkscreen.setAttribute('height', 297);
		silkscreen.setAttribute('preserveAspectRatio', 'none');
		silkscreen.setAttribute('clip-path', 'url(#board-clip)');
		silkscreen.classList.add('board-silkscreen');
		silkscreen.setAttribute('aria-hidden', 'true');
		svg.appendChild(silkscreen);

		// Lit LEDs glow through a per-LED CSS drop-shadow scaled by their
		// level (see .led/.led-rgb in styles.css) -- a plain blur of a white
		// LED would vanish against the white PCB.
		const ledLayer = document.createElementNS(SVG_NS, 'g');
		// The <title>s stay as hover tooltips, but 314 named graphics would
		// drown a screen reader
		ledLayer.setAttribute('aria-hidden', 'true');
		for (const led of BOARD_DATA.leds) {
			const c = document.createElementNS(SVG_NS, 'circle');
			c.setAttribute('cx', led.x);
			c.setAttribute('cy', led.y);
			c.setAttribute('r', LED_RADIUS);
			c.classList.add('led');
			c.dataset.row = led.row;
			c.dataset.col = led.col;
			const title = document.createElementNS(SVG_NS, 'title');
			title.textContent = `${led.ref}: row ${led.row}, column ${led.col}`;
			c.appendChild(title);
			ledLayer.appendChild(c);
			this.dotByIndex[led.row * MATRIX_COLS + led.col] = c;
			this._targets.push({ rgb: false, led });
		}

		for (const led of BOARD_DATA.rgb_leds) {
			// Diamond, not a circle, so RGB accent LEDs (a different click
			// target: a color picker, not the paint brush) are visually
			// obvious at a glance rather than indistinguishable from mono
			// LEDs until clicked.
			const c = document.createElementNS(SVG_NS, 'rect');
			const s = LED_RADIUS * 1.8;
			c.setAttribute('x', led.x - s / 2);
			c.setAttribute('y', led.y - s / 2);
			c.setAttribute('width', s);
			c.setAttribute('height', s);
			c.setAttribute('transform', `rotate(45 ${led.x} ${led.y})`);
			c.classList.add('led-rgb');
			const title = document.createElementNS(SVG_NS, 'title');
			title.textContent = `${led.ref}: colour LED, column ${led.col}. Click to set its colour.`;
			c.appendChild(title);
			c.addEventListener('click', (ev) => {
				ev.stopPropagation();
				if (!this.rgbBrush && this.onSelectRgb) this.onSelectRgb(led, { keyboard: false });
			});
			ledLayer.appendChild(c);
			this.rgbDotByRef.set(led.ref, c);
			this._targets.push({ rgb: true, led });
			// An RGB LED's three channels share one column (its shared anode
			// group) but each channel is a different row -- see
			// docs/LEDPWM_MATRIX.md and tools/extract_board_data.py.
			for (const row of [led.row, led.green_row, led.blue_row]) {
				const cell = row * MATRIX_COLS + led.col;
				if (!this._rgbRefsByCell.has(cell)) this._rgbRefsByCell.set(cell, []);
				this._rgbRefsByCell.get(cell).push(led.ref);
			}
		}
		svg.appendChild(ledLayer);

		// Keyboard cursor, on top of everything. Hidden until the board is
		// used from the keyboard. The presentation attributes are a fallback
		// for the .board-cursor rules in styles.css.
		const cursorLayer = document.createElementNS(SVG_NS, 'g');
		cursorLayer.setAttribute('aria-hidden', 'true');
		const cursor = document.createElementNS(SVG_NS, 'g');
		cursor.setAttribute('pointer-events', 'none');
		cursor.setAttribute('visibility', 'hidden');
		cursor.classList.add('board-cursor');
		for (const [cls, colour, width] of [
			['board-cursor-halo', '#f5e722', BOARD_CURSOR_HALO],
			['board-cursor-core', '#000', BOARD_CURSOR_CORE],
		]) {
			const ring = document.createElementNS(SVG_NS, 'circle');
			ring.setAttribute('r', BOARD_CURSOR_RADIUS);
			ring.setAttribute('fill', 'none');
			ring.setAttribute('stroke', colour);
			ring.setAttribute('stroke-width', width);
			ring.classList.add(cls);
			cursor.appendChild(ring);
		}
		cursorLayer.appendChild(cursor);
		svg.appendChild(cursorLayer);
		this._cursorEl = cursor;
		this._cursor = this._centreTarget();
		this._drawCursor();

		this._wirePointerEvents(svg);
		this._wireKeyboard(svg);

		this.container.innerHTML = '';
		this.container.appendChild(svg);
		this.svg = svg;
	}

	_wirePointerEvents(svg) {
		// onPaintAt returns false when no LED was in reach
		const paintAt = (ev) => {
			if (!this.onPaintAt) return true;
			const pt = svg.createSVGPoint();
			pt.x = ev.clientX;
			pt.y = ev.clientY;
			const mm = pt.matrixTransform(svg.getScreenCTM().inverse());
			return this.onPaintAt(mm.x, mm.y) !== false;
		};
		// WCAG 2.5.8: the LEDs are far under 24px on a phone, and as close
		// together as on the real board. That layout is essential (it is the
		// badge), so the exception applies; to help anyway, a tap in white
		// mode that reaches no white LED picks the nearest colour LED.
		let missedAt = null; // board position of a pointerdown that painted nothing
		svg.addEventListener('pointerdown', (ev) => {
			missedAt = null;
			// The keyboard carries on from where the pointer went down
			const mm = this._clientToBoard(svg, ev.clientX, ev.clientY);
			if (mm) {
				this._cursor = this._nearestTarget(mm.x, mm.y);
				this._showCursor(false);
			}
			// Capturing the pointer here (needed so drag-painting keeps
			// working even once the cursor leaves the svg's bounds) would
			// retarget the click synthesized from the matching pointerup to
			// the svg element instead of whatever was actually clicked --
			// which would silently break the RGB LEDs' own click listeners.
			// Let clicks on those fire normally instead.
			if (ev.target.closest('.led-rgb') && !this.rgbBrush) return;
			this._painting = true;
			svg.setPointerCapture(ev.pointerId);
			if (!paintAt(ev) && !this.rgbBrush) missedAt = mm;
		});
		svg.addEventListener('pointermove', (ev) => {
			if (!this._painting) return;
			if (paintAt(ev)) missedAt = null;
		});
		// After the pointerup, so the focus the click gives the svg is
		// settled before the colour editor takes it
		svg.addEventListener('click', () => {
			const mm = missedAt;
			missedAt = null;
			if (!mm || this.rgbBrush || !this.onSelectRgb) return;
			const t = this._targets[this._nearestTarget(mm.x, mm.y)];
			if (t && t.rgb && Math.hypot(t.led.x - mm.x, t.led.y - mm.y) <= BOARD_RGB_TAP_RADIUS) {
				this.onSelectRgb(t.led, { keyboard: false });
			}
		});
		for (const type of ['pointerup', 'pointercancel', 'pointerleave']) {
			svg.addEventListener(type, () => {
				this._painting = false;
			});
		}
	}

	_clientToBoard(svg, clientX, clientY) {
		const ctm = svg.getScreenCTM();
		if (!ctm) return null;
		const pt = svg.createSVGPoint();
		pt.x = clientX;
		pt.y = clientY;
		return pt.matrixTransform(ctm.inverse());
	}

	// --- Keyboard ---------------------------------------------------
	// Arrows move the cursor to the nearest LED in that direction, Shift+Arrow
	// paints the LEDs it leaves and lands on, Space paints, Enter on a
	// diamond opens the colour editor (paints in colour-brush mode),
	// Delete/Backspace erases, Home goes back to the centre. Painting goes
	// through onPaintAt like the pointer, so brush size, eraser and brush
	// mode all apply.

	_wireKeyboard(svg) {
		svg.addEventListener('keydown', (ev) => {
			if (ev.altKey || ev.ctrlKey || ev.metaKey) return;
			const dir = BOARD_ARROWS[ev.key];
			if (dir) {
				ev.preventDefault();
				this._showCursor(true);
				const next = this._targetInDirection(this._cursor, dir);
				if (next < 0) {
					if (ev.shiftKey) this._paintCursor();
					this._announce(`Edge of the board. ${this._describe(this._cursor)}`);
					return;
				}
				if (ev.shiftKey) this._paintCursor();
				this._cursor = next;
				this._drawCursor();
				if (ev.shiftKey) this._paintCursor();
				this._announceCursor();
				return;
			}
			switch (ev.key) {
				case ' ':
				case 'Spacebar':
					ev.preventDefault();
					if (ev.repeat) return;
					this._showCursor(true);
					this._paintCursor();
					this._announceCursor();
					break;
				case 'Enter': {
					ev.preventDefault();
					if (ev.repeat) return;
					this._showCursor(true);
					const t = this._targets[this._cursor];
					if (t && t.rgb && !this.rgbBrush) {
						if (this.onSelectRgb) this.onSelectRgb(t.led, { keyboard: true });
						return;
					}
					this._paintCursor();
					this._announceCursor();
					break;
				}
				case 'Delete':
				case 'Backspace':
					ev.preventDefault();
					this._showCursor(true);
					this._eraseCursor();
					this._announceCursor();
					break;
				case 'Home':
					ev.preventDefault();
					this._showCursor(true);
					this._cursor = this._centreTarget();
					this._drawCursor();
					this._announceCursor();
					break;
				default:
					break;
			}
		});
		svg.addEventListener('focus', () => {
			// A mouse click focuses the svg too; only show the cursor for
			// keyboard focus
			let keyboard = true;
			try {
				keyboard = svg.matches(':focus-visible');
			} catch (e) {
				// no :focus-visible support: show it anyway
			}
			if (keyboard) {
				this._showCursor(true);
				this._announceCursor();
			}
		});
		svg.addEventListener('blur', () => this._showCursor(false));
	}

	_showCursor(visible) {
		if (!this._cursorEl) return;
		this._cursorEl.setAttribute('visibility', visible ? 'visible' : 'hidden');
		if (visible) this._drawCursor();
	}

	_drawCursor() {
		const t = this._targets[this._cursor];
		if (!t || !this._cursorEl) return;
		this._cursorEl.setAttribute('transform', `translate(${t.led.x} ${t.led.y})`);
	}

	_paintCursor() {
		const t = this._targets[this._cursor];
		if (t && this.onPaintAt) this.onPaintAt(t.led.x, t.led.y);
	}

	_eraseCursor() {
		const t = this._targets[this._cursor];
		if (!t) return;
		if (this.onEraseAt) {
			this.onEraseAt(t.led.x, t.led.y);
			return;
		}
		if (!this.onPaintAt) return;
		const eraser = document.getElementById('erase-mode');
		if (!eraser) return;
		const was = eraser.checked;
		eraser.checked = true;
		try {
			this.onPaintAt(t.led.x, t.led.y);
		} finally {
			eraser.checked = was;
		}
	}

	// The LED nearest the middle of the board
	_centreTarget() {
		const b = this.bounds;
		return this._nearestTarget(b.minX + b.width / 2, b.minY + b.height / 2);
	}

	_nearestTarget(x, y) {
		let best = 0;
		let bestDist = Infinity;
		this._targets.forEach((t, i) => {
			const d = Math.hypot(t.led.x - x, t.led.y - y);
			if (d < bestDist) {
				bestDist = d;
				best = i;
			}
		});
		return best;
	}

	// Nearest LED within 45 degrees of the direction, scored by distance
	// plus twice the sideways offset, so the cursor stays on its line.
	// Returns -1 when there is none.
	_targetInDirection(from, [ux, uy]) {
		const origin = this._targets[from];
		if (!origin) return -1;
		let best = -1;
		let bestScore = Infinity;
		this._targets.forEach((t, i) => {
			if (i === from) return;
			const dx = t.led.x - origin.led.x;
			const dy = t.led.y - origin.led.y;
			const along = dx * ux + dy * uy;
			const side = Math.abs(dx * uy - dy * ux);
			if (along <= 0 || side > along) return;
			const score = Math.hypot(dx, dy) + 2 * side;
			if (score < bestScore) {
				bestScore = score;
				best = i;
			}
		});
		return best;
	}

	_describe(index) {
		const t = this._targets[index];
		if (!t) return '';
		if (t.rgb) {
			const [r, g, b] = this.getRgb(t.led);
			return `${t.led.ref}, colour LED, colour ${r} ${g} ${b}`;
		}
		const n = this.frame[t.led.row * MATRIX_COLS + t.led.col];
		return `${t.led.ref}, white LED, level ${n} of 255`;
	}

	_announceCursor() {
		this._announce(this._describe(this._cursor));
	}

	// Writes to #board-live at most once per BOARD_ANNOUNCE_MS; the last
	// message in a burst always gets through
	_announce(text) {
		this._announceText = text;
		if (this._announceTimer) return;
		const wait = this._announceLast + BOARD_ANNOUNCE_MS - Date.now();
		const flush = () => {
			this._announceTimer = null;
			this._announceLast = Date.now();
			const live = document.getElementById('board-live');
			if (live) live.textContent = this._announceText;
		};
		if (wait <= 0) flush();
		else this._announceTimer = setTimeout(flush, wait);
	}

	setPixel(row, col, brightness) {
		if (row < 0 || row >= MATRIX_ROWS || col < 0 || col >= MATRIX_COLS) return;
		const cell = row * MATRIX_COLS + col;
		this.frame[cell] = brightness;
		const dot = this.dotByIndex[cell];
		if (dot) dot.style.setProperty('--level', brightness / 255);
		this._refreshRgbAtCell(cell);
	}

	setFrame(frame) {
		this.frame.set(frame);
		for (let i = 0; i < PIXEL_COUNT; i++) {
			const dot = this.dotByIndex[i];
			if (dot) dot.style.setProperty('--level', this.frame[i] / 255);
		}
		for (const led of BOARD_DATA.rgb_leds) this._refreshRgbSwatch(led);
	}

	_refreshRgbAtCell(cell) {
		const refs = this._rgbRefsByCell.get(cell);
		if (!refs) return;
		for (const ref of refs) {
			const led = BOARD_DATA.rgb_leds.find((l) => l.ref === ref);
			if (led) this._refreshRgbSwatch(led);
		}
	}

	_refreshRgbSwatch(led) {
		const dot = this.rgbDotByRef.get(led.ref);
		if (!dot) return;
		const [r, g, b] = this.getRgb(led);
		const lit = r || g || b;
		// Unlit: fall back to the CSS package color rather than black
		dot.style.fill = lit ? `rgb(${r}, ${g}, ${b})` : '';
		dot.style.setProperty('--glow', lit ? `rgb(${r}, ${g}, ${b})` : 'transparent');
	}

	// Each RGB LED's three channels are three ordinary cells in `frame`
	// (see docs/LEDPWM_MATRIX.md) -- these are just convenience wrappers
	// around setPixel()/frame reads for those three cells.
	getRgb(led) {
		return [
			this.frame[led.row * MATRIX_COLS + led.col],
			this.frame[led.green_row * MATRIX_COLS + led.col],
			this.frame[led.blue_row * MATRIX_COLS + led.col],
		];
	}

	setRgb(led, r, g, b) {
		this.setPixel(led.row, led.col, r);
		this.setPixel(led.green_row, led.col, g);
		this.setPixel(led.blue_row, led.col, b);
	}

	getFrame() {
		return this.frame.slice();
	}

	clear() {
		this.setFrame(new Uint8Array(PIXEL_COUNT));
	}
}
